int IsExistEL(MGraph G) {
    //采用邻接矩阵存储，判断图是否存在EL 路径
    int degree, i, j, count = 0;
    for (i = 0; i < G.numVertices; i++) {
        degree = 0;
        for (j = 0; j < G.numVertices; j++)   //依次计算各个顶点的度
            degree += G.Edge[i][j];
        if (degree % 2 != 0)                  //对度为奇数的顶点计数
            count++;
    }
    if (count == 0 || count == 2)             //存在EL 路径，返回 1
        return 1;
    else                                      //不存在EL 路径，返回0
        return 0;
}

