//访问标记数组
bool visited[MAX_VERTEX_NUM];
void DFSTraverse(Graph G) {
    for (v = 0; v < G.vexnum; ++v)          //初始化访问标记数组
        visited[v] = FALSE;
    time = 0;                              //本代码从 v=0 开始遍历
