1）算法的基本设计思想：建立图 G 各顶点的入度表 degree[]。选择入度为 0 的顶点 v，将 v 的所有邻接点的入度减 1，重复执行这个过程。若每次选中的入度为 0 的顶点有且仅有一个，且共进行了 G.numVertices 次，则意味着存在唯一的拓扑序列，返回 1；否则不存在拓扑序列，或者存在多个拓扑序列，返回 0。
2）用 C 语言描述的算法如下：

int uniquely(MGraph G) {          // 判定有向图是否存在唯一的拓扑序列
    int *degree, i, j, in0, count = 0, prev;
    degree = (int *)malloc(G.numVertices * sizeof(int));
    for (j = 0; j < G.numVertices; j++) {    // 计算各顶点的入度
        degree[j] = 0;
        for (i = 0; i < G.numVertices; i++)
            degree[j] += G.Edge[i][j];
    }
    in0 = -1;
    for (i = 0; i < G.numVertices; i++) {
        if (degree[i] == 0) {                // 入度为 0 的顶点
            if (in0 == -1) in0 = i;
            else in0 = -2;                   // 有多个入度为 0 的顶点
        }
    }
    while (in0 >= 0) {
        count++;
        prev = in0;
        in0 = -1;
        for (j = 0; j < G.numVertices; j++) {
            if (G.Edge[prev][j] != 0) {      // 邻接点入度值减 1
                if (--degree[j] == 0) {
                    if (in0 == -1) in0 = j;  // 入度为 0 的顶点
                    else in0 = -2;           // 有多个入度为 0 的顶点
                }
            }
        }
    }
    free(degree);
    if (count == G.numVertices) return 1;
    else return 0;
}

【解答】 对二叉排序树来说，其中序遍历序列为一个递增有序序列。因此，对给定的二叉树进行中序遍历，若始终能保持前一个值比后一个值小，则说明该二叉树是一棵二叉排序树。算法实现如下：

```c
// predt 为全局变量，保存当前结点中序前驱的值，初值为 -∞
KeyType predt = -32767;

int JudgeBST(BiTree bt) {
    int b1, b2;
    if (bt == NULL) return 1;                 // 空树
    else {
        b1 = JudgeBST(bt->lchild);            // 判断左子树是否是二叉排序树
        if (b1 == 0 || predt >= bt->data)     // 若左子树返回值为0，或前驱大于或等于当前结点
            return 0;                         // 则不是二叉排序树
        predt = bt->data;                     // 保存当前结点的关键字
        b2 = JudgeBST(bt->rchild);            // 判断右子树
        return b2;                            // 返回右子树的结果
    }
}
```

【解答】 算法思想：设二叉树采用二叉链表存储结构。在二叉排序树中，查找一次就下降一层。因此，查找该结点所用的次数就是该结点在二叉排序树中的层次。采用二叉排序树非递归查找算法，用 n 保存查找层次，每查找一次，n就加1，直到找到相应的结点。算法如下：

```c
int level(BiTree bt, BSTNode *p) {
    int n = 0;                                // 统计查找次数
    BiTree t = bt;
    if (bt != NULL) {
        n++;
        while (t->data != p->data) {
            if (p->data < t->data)
                t = t->lchild;                // 在左子树中查找
            else
                t = t->rchild;                // 在右子树中查找
            n++;                              // 层次加 1
        }
    }
    return n;
}
```

【解答】 设置二叉树的平衡标记balance，以标记返回二叉树 bt 是否为平衡二叉树，若为平衡二叉树，则返回1，否则返回0；h为二叉树 bt 的高度。采用后序遍历的递归算法：
1）若bt为空，则高度为 0，balance=1。
2）若bt 仅有根结点，则高度为1，balance=1。
3）否则，对bt的左右子树执行递归运算，返回左右子树的高度和平衡标记，bt 的高度为最高子树的高度加1。若左右子树的高度差大于 1，则balance=0；若左右子树的高度差小于或等于 1，且左右子树都平衡时，balance=1，否则 balance=0。
算法如下：

```c
void Judge_AVL(BiTree bt, int &balance, int &h) {
    int b1 = 0, br = 0, h1 = 0, hr = 0;       // 左右子树的平衡标记和高度
    if (bt == NULL) {                         // 空树，高度为 0
        h = 0; balance = 1;
    }
    else if (bt->lchild == NULL && bt->rchild == NULL) {   // 仅有根结点，则高度为 1
        h = 1; balance = 1;
    }
    else {
        Judge_AVL(bt->lchild, b1, h1);        // 递归判断左子树
        Judge_AVL(bt->rchild, br, hr);        // 递归判断右子树
        h = (h1 > hr ? h1 : hr) + 1;
        if (abs(h1 - hr) < 2) balance = b1 && br;   // &&为逻辑与，即左右子树都平衡时，二叉树平衡
        else balance = 0;
    }
}
```

【解答】 在一棵二叉排序树中，最左下结点即关键字最小的结点，最右下结点即关键字最大的结点，本算法只要找出这两个结点即可，而不需要比较关键字。算法如下：

```c
KeyType MinKey(BSTNode *bt) {
    while (bt->lchild != NULL) bt = bt->lchild;
    return bt->data;
}

KeyType MaxKey(BSTNode *bt) {
    while (bt->rchild != NULL)              // 求出二叉排序树中最大关键字结点
        bt = bt->rchild;
    return bt->data;
}
```

【解答】本题可采用基于快速排序的划分思想来设计算法，只需遍历一次即可，其时间复杂度为 O(n)，空间复杂度为 O(1)。假设表为 L[1..n]，基本思想是：先从前往后找到一个偶数元素 L(i)，再从后往前找到一个奇数元素 L(j)，将二者交换；重复上述过程直到 i>j。算法的实现如下：
void move(ElemType A[], int len) {
    // 对表 A 按奇偶进行一趟划分
    int i = 0, j = len - 1;                 // i 表示左端偶数元素的下标；j 表示右端奇数元素的下标
    while (i < j) {
        while (i < j && A[i] % 2 != 0) i++;   // 从前往后找到一个偶数元素
        while (i < j && A[j] % 2 != 1) --j;   // 从后往前找到一个奇数元素
        if (i < j) {                          // 交换这两个元素
            Swap(&A[i], &A[j]);
            i++;
            j--;
        }
    }
}
